"""Explicit comparison of saved synthetic purchases, with frozen history."""
JS=r'''
let purchaseComparisonSequence=0;
function renderPurchaseComparisonSaved(proposal){
 let submitted=false;const sequence=++purchaseComparisonSequence,dataset=$('dataset').value;
 let box=$('purchase-comparison');if(!box){box=document.createElement('section');box.id='purchase-comparison';box.className='card';$('review-panel').append(box)}box.replaceChildren();
 const h=document.createElement('h2');h.textContent='COMPARAR CONDICIONES DE COMPRA';box.append(h);
 const note=document.createElement('p');note.textContent='Compara la misma cantidad y proveedor, con o sin déficit. Las referencias y aceptaciones declaradas quedan sin verificar. Guardar no modifica la propuesta original. La previsión compensa movimientos al cierre de cada día y no garantiza cobros, disponibilidad actual ni cobertura completa de obligaciones.';box.append(note);
 const fields={};function input(key,label,type='text'){const l=document.createElement('label'),i=document.createElement('input');l.textContent=label;i.type=type;l.append(i);box.append(l);fields[key]=i;return i}
 input('label','Nombre de la alternativa').value='Alternativa de negociación';input('actor','Responsable');
 input('price','Nuevo precio por unidad (opcional)','number').step='any';input('discount','Descuento porcentual alternativo (opcional)','number').step='any';input('due','Nuevo vencimiento de mercancía (opcional)','date');
 const originLabel=document.createElement('label');originLabel.textContent='Origen de las condiciones modificadas';const origin=document.createElement('select');for(const [v,t] of [['HYPOTHETICAL','Hipótesis para negociar'],['DOCUMENTED','Oferta documentada, sin verificar'],['UNCONFIRMED','Sin confirmar']]){const o=document.createElement('option');o.value=v;o.textContent=t;origin.append(o)}originLabel.append(origin);box.append(originLabel);
 input('source','Referencia del soporte (obligatoria para oferta documentada)');
 const quotaLabel=document.createElement('label'),quotaEnabled=document.createElement('input');quotaEnabled.type='checkbox';quotaLabel.append(quotaEnabled,document.createTextNode(' Sustituir el calendario completo de cuotas'));box.append(quotaLabel);const quotas=document.createElement('div');quotas.hidden=true;box.append(quotas);const addQuota=document.createElement('button');addQuota.type='button';addQuota.textContent='Añadir cuota';quotas.append(addQuota);const quotaRows=[];addQuota.onclick=()=>{const row=document.createElement('div'),component=document.createElement('select'),amount=document.createElement('input'),due=document.createElement('input'),remove=document.createElement('button');for(const [v,t] of [['MERCHANDISE','Mercancía'],['FREIGHT','Portes']]){const o=document.createElement('option');o.value=v;o.textContent=t;component.append(o)}amount.type='number';amount.step='0.01';amount.min='0.01';amount.setAttribute('aria-label','Importe de cuota con IVA');due.type='date';due.setAttribute('aria-label','Vencimiento de cuota');remove.type='button';remove.textContent='Eliminar cuota';row.append(component,amount,due,remove);quotas.append(row);const item={row,component,amount,due};quotaRows.push(item);remove.onclick=()=>{quotaRows.splice(quotaRows.indexOf(item),1);row.remove()}};quotaEnabled.onchange=()=>{quotas.hidden=!quotaEnabled.checked};
 const button=document.createElement('button');button.type='button';button.textContent='Comparar y conservar estudio';box.append(button);
 const output=document.createElement('div');output.setAttribute('aria-live','polite');box.append(output);
 function render(items){output.replaceChildren();for(const item of items){const r=item.record,title=document.createElement('h3');title.textContent=(item.stale?'HISTÓRICO DESACTUALIZADO · ':'ESTUDIO GUARDADO · ')+stockDate(r.created_at);output.append(title);const table=document.createElement('table');const head=document.createElement('tr');for(const t of ['Condición','Total a pagar','Ahorro','Saldo mínimo','Falta para reserva','Fecha de saldo mínimo','Estado']){const th=document.createElement('th');th.textContent=t;head.append(th)}table.append(head);const rows=[{label:'Propuesta original',result:r.baseline,saving:'0'},...r.alternatives];for(const a of rows){const tr=document.createElement('tr'),v=a.result;for(const value of [a.label,v.total?money(v.total)+' EUR':'Pendiente',a.saving===null?'Pendiente':money(a.saving)+' EUR',v.scenario?money(v.scenario.minimum_balance)+' EUR':'Pendiente',v.scenario?money(v.scenario.deficit)+' EUR':'Pendiente',v.scenario?stockDate(v.scenario.minimum_date):'Pendiente',v.status==='PENDING'?v.message:v.status==='SHORTFALL'?'No respeta la reserva':'Respeta la reserva en el escenario']){const td=document.createElement('td');td.textContent=value;tr.append(td)}table.append(tr);if(a.conditions){const p=document.createElement('p');p.textContent=Object.entries(a.conditions).map(([k,c])=>k+': '+({DOCUMENTED:'Documentada, sin verificar',HYPOTHETICAL:'Hipótesis para negociar',UNCONFIRMED:'Sin confirmar'}[c.origin])+(c.source_reference?' · '+c.source_reference:'')+(c.validity_status==='EXPIRED_AT_COMPARISON'?' · VIGENCIA CADUCADA':'')).join('; ');output.append(p)}}output.append(table);for(const a of rows){if(a.result.payments){const p=document.createElement('p');p.textContent=a.label+' · Pagos: '+a.result.payments.map(i=>stockDate(i.due_date)+': '+money(i.amount)+' EUR').join('; ');output.append(p)}}const p=document.createElement('p');p.textContent='Sin ganadora automática. No acredita viabilidad final ni aceptación verificada. Identificador: '+r.comparison_id;output.append(p)}}
 button.onclick=async()=>{submitted=true;button.disabled=true;try{const patch={};if(fields.price.value!=='')patch.unit_price=fields.price.value;if(fields.discount.value!==''){if(fields.price.value==='')throw Error('Indica el precio antes de descuentos para comparar el descuento.');patch.pricing_mode='BEFORE_DISCOUNT';patch.discount_mode='PERCENT';patch.discount_value=fields.discount.value}if(fields.due.value)patch.due_date=fields.due.value;if(quotaEnabled.checked)patch.payment_installments=quotaRows.map(i=>({component:i.component.value,amount:i.amount.value,due_date:i.due.value}));if(!Object.keys(patch).length)throw Error('Introduce un precio o vencimiento alternativo. Si hay cuotas, el nuevo vencimiento debe ser coherente con su calendario completo.');const conditions=Object.fromEntries(Object.keys(patch).map(k=>[k,{origin:origin.value,acceptance:'PENDING',source_reference:fields.source.value||null}]));const r=await api('/api/purchases/comparisons',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,proposal_id:proposal.proposal_id,documentary_context_fingerprint:state.documentary_context.fingerprint,actor:fields.actor.value,alternatives:[{label:fields.label.value,patch,conditions}]})});if(sequence!==purchaseComparisonSequence||dataset!==$('dataset').value)return;render([{record:r,stale:false}])}catch(e){if(sequence===purchaseComparisonSequence)output.textContent=e.message}finally{button.disabled=false}};
 api('/api/purchases/comparisons/read',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,proposal_id:proposal.proposal_id})}).then(r=>{if(!submitted&&sequence===purchaseComparisonSequence&&dataset===$('dataset').value)render(r.comparisons)}).catch(e=>{if(sequence===purchaseComparisonSequence)output.textContent=e.message});
}
'''
